a<-commandArgs(TRUE);p<-a[1];s<-read.csv(file.path(p,'summary.csv'));d<-subset(s,type=='food' & tick==1000);keys<-c('48 120 fixed','48 80 fixed','96 120 fixed','96 80 fixed','48 120 staggered','48 80 staggered','96 120 staggered','96 80 staggered');v<-d[match(keys,d$label),];stopifnot(!anyNA(v$mean));png(file.path(p,'food-effects.png'),width=1500,height=900,res=160);par(mar=c(8,5,3,1));plot(NA,xlim=c(.5,8.5),ylim=range(c(0,v$lower,v$upper)),xaxt='n',xlab='',ylab='Food effect on mixture contrast (agents)',main='How food effects vary with starting density and reproduction');abline(h=0,lty=2,col='gray50');axis(1,at=1:8,labels=c('48 / 120','48 / 80','96 / 120','96 / 80','48 / 120','48 / 80','96 / 120','96 / 80'),tick=FALSE,line=.2);mtext('Same ages',side=1,at=2.5,line=2.5);mtext('Staggered ages',side=1,at=6.5,line=2.5);mtext('Founder count / reproduction threshold',side=1,line=4.6);cols<-rep(c('#2166ac','#b2182b'),each=4);arrows(1:8,v$lower,1:8,v$upper,angle=90,code=3,length=.04,col=cols);points(1:8,v$mean,pch=16,col=cols,cex=1.2);mtext('Limited minus original food; points and 95% paired intervals',side=1,line=6,cex=.8);dev.off()
